import torch.distributed as dist
import torch.nn.functional as F
import inspect
from typing import List, Tuple


def _get_core_model(model):
    if hasattr(model, "model"):
        return model.model
    if hasattr(model, "base_model"):
        return model.base_model
    if hasattr(model, "transformer"):
        return model.transformer
    return model


def _get_layers(core):
    if hasattr(core, "layers"):
        return core.layers
    if hasattr(core, "decoder") and hasattr(core.decoder, "layers"):
        return core.decoder.layers
    raise AttributeError("Could not find layers in model")


def _get_embed_tokens(core):
    if hasattr(core, "embed_tokens"):
        return core.embed_tokens
    if hasattr(core, "get_input_embeddings"):
        return core.get_input_embeddings()
    raise AttributeError("Could not find embedding layer in model")


def _get_norm(core):
    if hasattr(core, "norm"):
        return core.norm
    if hasattr(core, "final_layernorm"):
        return core.final_layernorm
    return None


def _get_hidden_size(model, core, embed_tokens):
    if hasattr(model, "config") and hasattr(model.config, "hidden_size"):
        return model.config.hidden_size
    if hasattr(core, "config") and hasattr(core.config, "hidden_size"):
        return core.config.hidden_size
    if hasattr(embed_tokens, "weight"):
        return embed_tokens.weight.shape[1]
    return None


def _partition_layers(num_layers: int, world_size: int, rank: int) -> Tuple[int, int]:
    if world_size <= 0:
        return 0, num_layers
    base = num_layers // world_size
    remainder = num_layers % world_size
    start = rank * base + min(rank, remainder)
    end = start + base + (1 if rank < remainder else 0)
    return start, end


def _make_causal_mask(input_shape: Tuple[int, int], dtype: torch.dtype, device: torch.device, past_key_values_length: int = 0):
    bsz, tgt_len = input_shape
    mask = torch.full((tgt_len, tgt_len + past_key_values_length), torch.finfo(dtype).min, device=device)
    mask_cond = torch.arange(mask.size(-1), device=device)
    mask = mask.masked_fill(mask_cond < (torch.arange(tgt_len, device=device).unsqueeze(1) + past_key_values_length), 0)
    if past_key_values_length > 0:
        mask = mask[:, past_key_values_length:]
    mask = mask.to(dtype)
    mask = mask.unsqueeze(0).unsqueeze(0).expand(bsz, 1, tgt_len, tgt_len + past_key_values_length)
    return mask


def _expand_mask(mask: torch.Tensor, dtype: torch.dtype, tgt_len: int = None):
    bsz, src_len = mask.shape
    tgt_len = src_len if tgt_len is None else tgt_len
    expanded_mask = mask[:, None, None, :].expand(bsz, 1, tgt_len, src_len).to(dtype)
    inverted_mask = 1.0 - expanded_mask
    return inverted_mask.masked_fill(inverted_mask.bool(), torch.finfo(dtype).min)


def _prepare_decoder_attention_mask(attention_mask, input_shape, inputs_embeds, past_key_values_length):
    bsz, tgt_len = input_shape
    if attention_mask is not None:
        expanded_attn_mask = _expand_mask(attention_mask, inputs_embeds.dtype, tgt_len)
    else:
        expanded_attn_mask = None

    causal_mask = None
    if tgt_len > 1:
        causal_mask = _make_causal_mask(input_shape, inputs_embeds.dtype, inputs_embeds.device, past_key_values_length)

    if expanded_attn_mask is None:
        return causal_mask
    if causal_mask is None:
        return expanded_attn_mask
    return expanded_attn_mask + causal_mask


def _build_attention_and_positions(core, batch_size: int, seq_len: int, inputs_embeds: torch.Tensor, device: torch.device, dtype: torch.dtype):
    if hasattr(core, "_prepare_decoder_attention_mask"):
        attention_mask = core._prepare_decoder_attention_mask(None, (batch_size, seq_len), inputs_embeds, 0)
    else:
        attention_mask = _prepare_decoder_attention_mask(None, (batch_size, seq_len), inputs_embeds, 0)
    position_ids = torch.arange(0, seq_len, device=device, dtype=torch.long).unsqueeze(0).expand(batch_size, -1)
    return attention_mask, position_ids


def _layer_forward(layer, hidden_states, attention_mask, position_ids):
    sig = inspect.signature(layer.forward)
    kwargs = {}
    if "attention_mask" in sig.parameters:
        kwargs["attention_mask"] = attention_mask
    if "position_ids" in sig.parameters:
        kwargs["position_ids"] = position_ids
    if "past_key_value" in sig.parameters:
        kwargs["past_key_value"] = None
    if "output_attentions" in sig.parameters:
        kwargs["output_attentions"] = False
    if "use_cache" in sig.parameters:
        kwargs["use_cache"] = False
    if "cache_position" in sig.parameters:
        kwargs["cache_position"] = None
    outputs = layer(hidden_states, **kwargs)
    if isinstance(outputs, tuple):
        return outputs[0]
    return outputs


def _get_lm_head(model, core):
    if hasattr(model, "lm_head"):
        return model.lm_head
    if hasattr(core, "lm_head"):
        return core.lm_head
    if hasattr(model, "output_layer"):
        return model.output_layer
    raise AttributeError("Could not find lm_head in model")


# Main training step

def train_step_pipeline_afab(model, inputs: List[torch.Tensor], targets: List[torch.Tensor], device: torch.device, dtype: torch.dtype):
    if dist.is_available() and dist.is_initialized():
        rank = dist.get_rank()
        world_size = dist.get_world_size()
    else:
        rank = 0
        world_size = 1

    core = _get_core_model(model)
    layers = _get_layers(core)
    embed_tokens = _get_embed_tokens(core)
    norm = _get_norm(core)
    lm_head = _get_lm_head(model, core)

    num_layers = len(layers)
    start, end = _partition_layers(num_layers, world_size, rank)
    local_layers = list(layers[start:end])

    hidden_size = _get_hidden_size(model, core, embed_tokens)
    if hidden_size is None:
        raise ValueError("Hidden size could not be determined")

    num_microbatches = len(inputs) if inputs is not None else len(targets)

    if dist.is_available() and dist.is_initialized() and world_size > 1:
        if rank == 0:
            shapes = torch.tensor([[mb.shape[0], mb.shape[1]] for mb in inputs], device=device, dtype=torch.long)
        else:
            shapes = torch.empty((num_microbatches, 2), device=device, dtype=torch.long)
        dist.broadcast(shapes, src=0)
    else:
        shapes = torch.tensor([[mb.shape[0], mb.shape[1]] for mb in inputs], device=device, dtype=torch.long)

    forward_cache = []

    for idx in range(num_microbatches):
        if rank == 0:
            input_ids = inputs[idx].to(device)
            if input_ids.dtype != torch.long:
                input_ids = input_ids.long()
            hidden_states = embed_tokens(input_ids)
            hidden_states = hidden_states.to(device=device, dtype=dtype)
            input_activation = None
        else:
            mb_shape = shapes[idx]
            batch_size = int(mb_shape[0].item())
            seq_len = int(mb_shape[1].item())
            recv_tensor = torch.empty((batch_size, seq_len, hidden_size), device=device, dtype=dtype)
            if world_size > 1:
                dist.recv(recv_tensor, src=rank - 1)
            input_activation = recv_tensor.detach().requires_grad_(True)
            hidden_states = input_activation

        if local_layers:
            if rank == 0:
                batch_size, seq_len = input_ids.shape
            else:
                batch_size, seq_len, _ = hidden_states.shape
            attention_mask, position_ids = _build_attention_and_positions(core, batch_size, seq_len, hidden_states, device, dtype)
            for layer in local_layers:
                hidden_states = _layer_forward(layer, hidden_states, attention_mask, position_ids)

        if rank != world_size - 1:
            if world_size > 1:
                dist.send(hidden_states.detach(), dst=rank + 1)
            forward_cache.append({"input": input_activation, "output": hidden_states})
        else:
            if norm is not None:
                hidden_states = norm(hidden_states)
            logits = lm_head(hidden_states)
            target_ids = targets[idx].to(device)
            if target_ids.dtype != torch.long:
                target_ids = target_ids.long()
            forward_cache.append({"input": input_activation, "logits": logits, "targets": target_ids})

    for idx in reversed(range(num_microbatches)):
        if rank == world_size - 1:
            logits = forward_cache[idx]["logits"]
            target_ids = forward_cache[idx]["targets"]
            loss = F.cross_entropy(logits.view(-1, logits.size(-1)), target_ids.view(-1), reduction="mean")
            loss = loss / num_microbatches
            loss.backward()
            if rank > 0 and world_size > 1:
                grad_to_send = forward_cache[idx]["input"].grad
                dist.send(grad_to_send.detach(), dst=rank - 1)
        else:
            grad = torch.empty_like(forward_cache[idx]["output"])
            if world_size > 1:
                dist.recv(grad, src=rank + 1)
            forward_cache[idx]["output"].backward(grad)
            if rank > 0 and world_size > 1:
                grad_to_send = forward_cache[idx]["input"].grad
                dist.send(grad_to_send.detach(), dst=rank - 1)
"}

